-- UNAPPROVED OFFLINE CANDIDATE. Execute only under a separately approved action envelope.
DO $persistent_review$ BEGIN
revoke all on function public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb),private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb) from public,anon,authenticated,service_role;
if exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in ('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'::regprocedure,'private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE') or exists(select 1 from (values('anon'),('authenticated'),('service_role')) acl_role(name) cross join (values('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'::regprocedure),('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)'::regprocedure)) f(id) where has_function_privilege(acl_role.name,f.id,'EXECUTE')) then raise exception 'Expected closed effective ACL'; end if;
 if exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in (to_regprocedure('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)'),to_regprocedure('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)')) and a.grantee<>p.proowner) then raise exception 'Unexpected Review grantee'; end if;
if exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in ('public.save_first_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure,'private.save_first_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE') or exists(select 1 from (values('anon'),('authenticated'),('service_role')) acl_role(name) cross join (values('public.save_first_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure),('private.save_first_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure)) f(id) where has_function_privilege(acl_role.name,f.id,'EXECUTE')) then raise exception 'Expected closed effective ACL'; end if;
 if exists(select 1 from (values('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'),('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)')) f(name) where not has_function_privilege('authenticated',f.name,'EXECUTE') or has_function_privilege('anon',f.name,'EXECUTE') or has_function_privilege('service_role',f.name,'EXECUTE')) or exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in (to_regprocedure('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'),to_regprocedure('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)')) and a.grantee=0 and a.privilege_type='EXECUTE') then raise exception 'Expected general Save baseline (URL pair authenticated-open, others closed)'; end if;
END $persistent_review$;
